"OLAYLAR_GEZGINLER:1883-02-01:0":{"b": ["Mombasa – Rabai – Taveta – Ngongo (Kikuyu sərhədi) – Naivasha – Baringo – Viktoriya gölü (Thomson, 1883)", "2a6e3fd0"], "d": ["Marşrut: Mombasa → Rabai → Taveta → Ngong (Kikuyu sərhədi) → Naivasha gölü → Baringo gölü → Kavirondo (Viktoriya gölü sahili). Səyahətin hamısı xəritədə səyahət xətti kimi göstərilir.", "b08adc33"]},
"OLAYLAR_GEZGINLER:1885-06-11:0":{"b": ["Perm – Yekaterinburq – Tümen (Kennan, Uraldan Sibirə giriş)", "51073c4e"], "d": ["Marşrut: Perm → Yekaterinburq → Tümen. Səyahətin hamısı xəritədə səyahət xətti kimi göstərilir.", "b54cc767"]},
"OLAYLAR_GEZGINLER:1885-06-30:0":{"b": ["Tümen – İşim – Omsk – Pavlodar – Semipalatinsk (Kennan, poçt yolu)", "38cf5734"], "d": ["Marşrut: Tümen → İşim → Omsk → Pavlodar → Semipalatinsk. Səyahətin hamısı xəritədə səyahət xətti kimi göstərilir.", "6e173245"]},
